import{_ as o,a as n,c as s,ac as a}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第四册：流利英语 · 全册短语与句型 · 第25–48课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第四册：流利英语 · 全册短语与句型 · 第25–48课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-4/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 全册短语与句型 · 第1–24课","link":"/life/english/new-concept/book-4/phrases-part-01"},"next":{"text":"第四册：流利英语 · 全册易错点","link":"/life/english/new-concept/book-4/mistakes"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 全册短语与句型 · 第1–24课","link":"/life/english/new-concept/book-4/phrases-part-01"},"next":{"text":"第四册：流利英语 · 全册易错点","link":"/life/english/new-concept/book-4/mistakes"}},"headers":[],"relativePath":"life/english/new-concept/book-4/phrases-part-02.md","filePath":"life/english/new-concept/book-4/phrases-part-02.md"}'),l={name:"life/english/new-concept/book-4/phrases-part-02.md"};function t(i,e,r,h,p,c){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="第四册-流利英语-·-全册短语与句型-·-第25–48课" tabindex="-1">第四册：流利英语 · 全册短语与句型 · 第25–48课 <a class="header-anchor" href="#第四册-流利英语-·-全册短语与句型-·-第25–48课" aria-label="Permalink to &quot;第四册：流利英语 · 全册短语与句型 · 第25–48课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><h2 id="lesson-25-·-名词化与施事信息" tabindex="-1">Lesson 25 · 名词化与施事信息 <a class="header-anchor" href="#lesson-25-·-名词化与施事信息" aria-label="Permalink to &quot;Lesson 25 · 名词化与施事信息 {#lesson-25-·-名词化与施事信息}&quot;">​</a></h2><ul><li>be exposed to — 接触某环境因素</li><li>interfere with — 干扰某过程</li></ul><p><strong>句型示范：</strong> A reduction in background noise coincided with fewer interruptions during the task.</p><p>A reduction… 是名词化主语；coincided with 只说明同时发生，没有直接宣称因果。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-025">进入本课</a></p><h2 id="lesson-26-·-完成式分词状语" tabindex="-1">Lesson 26 · 完成式分词状语 <a class="header-anchor" href="#lesson-26-·-完成式分词状语" aria-label="Permalink to &quot;Lesson 26 · 完成式分词状语 {#lesson-26-·-完成式分词状语}&quot;">​</a></h2><ul><li>leave behind — 留下痕迹</li><li>in relation to — 相对于某对象</li></ul><p><strong>句型示范：</strong> Having compared the layers, the researchers proposed a tentative sequence of events.</p><p>Having compared 表先行完成动作；researchers 同时是 compare 和 propose 的执行者；tentative 限定结论。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-026">进入本课</a></p><h2 id="lesson-27-·-第三条件句与过去反事实" tabindex="-1">Lesson 27 · 第三条件句与过去反事实 <a class="header-anchor" href="#lesson-27-·-第三条件句与过去反事实" aria-label="Permalink to &quot;Lesson 27 · 第三条件句与过去反事实 {#lesson-27-·-第三条件句与过去反事实}&quot;">​</a></h2><ul><li>set sail — 起航</li><li>in hindsight — 事后回看</li></ul><p><strong>句型示范：</strong> If the model had been tested earlier, the designers might have noticed the imbalance.</p><p>had been tested 是过去完成时被动条件；might have noticed 表对过去替代结果的谨慎推测。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-027">进入本课</a></p><h2 id="lesson-28-·-间接问句与疑问语序" tabindex="-1">Lesson 28 · 间接问句与疑问语序 <a class="header-anchor" href="#lesson-28-·-间接问句与疑问语序" aria-label="Permalink to &quot;Lesson 28 · 间接问句与疑问语序 {#lesson-28-·-间接问句与疑问语序}&quot;">​</a></h2><ul><li>in plain language — 用浅显语言</li><li>make sure — 确认某事</li></ul><p><strong>句型示范：</strong> Could you explain what this term means in plain language?</p><p>Could you explain 是礼貌主句；what this term means 为宾语从句，this term 在 means 前。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-028">进入本课</a></p><h2 id="lesson-29-·-使役与许可结构" tabindex="-1">Lesson 29 · 使役与许可结构 <a class="header-anchor" href="#lesson-29-·-使役与许可结构" aria-label="Permalink to &quot;Lesson 29 · 使役与许可结构 {#lesson-29-·-使役与许可结构}&quot;">​</a></h2><ul><li>allow for — 考虑到；为某因素留余地</li><li>move across — 横越某表面</li></ul><p><strong>句型示范：</strong> The air cushion allows the model to move across the smooth floor.</p><p>allows + the model + to move 是宾语加不定式补足语；air cushion 为提供条件的主语。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-029">进入本课</a></p><h2 id="lesson-30-·-介词-which-的关系从句" tabindex="-1">Lesson 30 · 介词 + which 的关系从句 <a class="header-anchor" href="#lesson-30-·-介词-which-的关系从句" aria-label="Permalink to &quot;Lesson 30 · 介词 + which 的关系从句 {#lesson-30-·-介词-which-的关系从句}&quot;">​</a></h2><ul><li>map out — 绘制分布图</li><li>below the surface — 在表面以下</li></ul><p><strong>句型示范：</strong> The pressure under which the sensor operates must be recorded.</p><p>under which 修饰 pressure；主句主语是整个名词短语，must be recorded 为谓语。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-030">进入本课</a></p><h2 id="lesson-31-·-独立主格的主语与分词" tabindex="-1">Lesson 31 · 独立主格的主语与分词 <a class="header-anchor" href="#lesson-31-·-独立主格的主语与分词" aria-label="Permalink to &quot;Lesson 31 · 独立主格的主语与分词 {#lesson-31-·-独立主格的主语与分词}&quot;">​</a></h2><ul><li>work with — 使用某材料创作</li><li>give shape to — 赋予具体形态</li></ul><p><strong>句型示范：</strong> The clay still damp, the sculptor covered the model before leaving.</p><p>The clay still damp 有自己的主语 clay 和形容词 damp，补充背景；主句主语是 sculptor。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-031">进入本课</a></p><h2 id="lesson-32-·-形容词前置的-as-让步结构" tabindex="-1">Lesson 32 · 形容词前置的 as 让步结构 <a class="header-anchor" href="#lesson-32-·-形容词前置的-as-让步结构" aria-label="Permalink to &quot;Lesson 32 · 形容词前置的 as 让步结构 {#lesson-32-·-形容词前置的-as-让步结构}&quot;">​</a></h2><ul><li>call into question — 对某事提出质疑</li><li>in the light of — 根据新信息重新考虑</li></ul><p><strong>句型示范：</strong> Limited as the evidence is, it gives us a reason to repeat the experiment.</p><p>Limited 前置，as 引导让步；it 指 evidence；主句主张重复检验而不是立即接受结论。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-032">进入本课</a></p><h2 id="lesson-33-·-平行结构与-not-only-but-also" tabindex="-1">Lesson 33 · 平行结构与 not only…but also <a class="header-anchor" href="#lesson-33-·-平行结构与-not-only-but-also" aria-label="Permalink to &quot;Lesson 33 · 平行结构与 not only…but also {#lesson-33-·-平行结构与-not-only-but-also}&quot;">​</a></h2><ul><li>learn by doing — 在实践中学习</li><li>build on — 在已有基础上发展</li></ul><p><strong>句型示范：</strong> The course teaches students to question claims, compare sources and explain their conclusions.</p><p>to 后三个动词 question、compare、explain 并列，共享不定式标记 to，宾语分别对应各动作。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-033">进入本课</a></p><h2 id="lesson-34-·-倾向表达与概率范围" tabindex="-1">Lesson 34 · 倾向表达与概率范围 <a class="header-anchor" href="#lesson-34-·-倾向表达与概率范围" aria-label="Permalink to &quot;Lesson 34 · 倾向表达与概率范围 {#lesson-34-·-倾向表达与概率范围}&quot;">​</a></h2><ul><li>tend to — 往往会，表示倾向</li><li>be likely to — 很可能会，仍保留例外</li></ul><p><strong>句型示范：</strong> In this club, new members tend to ask their peers for help before approaching an adult.</p><p>In this club 限定范围；tend to ask 表倾向；before approaching 与主语 new members 共享执行者。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-034">进入本课</a></p><h2 id="lesson-35-·-将来完成时与未来截止点" tabindex="-1">Lesson 35 · 将来完成时与未来截止点 <a class="header-anchor" href="#lesson-35-·-将来完成时与未来截止点" aria-label="Permalink to &quot;Lesson 35 · 将来完成时与未来截止点 {#lesson-35-·-将来完成时与未来截止点}&quot;">​</a></h2><ul><li>by the time — 到某个时间点时</li><li>on schedule — 按计划进度</li></ul><p><strong>句型示范：</strong> By the time the simulated crew arrives, the support team will have checked every system.</p><p>arrives 为未来时间从句的一般现在时；will have checked 表该时点前完成。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-035">进入本课</a></p><h2 id="lesson-36-·-倍数比较与百分比基数" tabindex="-1">Lesson 36 · 倍数比较与百分比基数 <a class="header-anchor" href="#lesson-36-·-倍数比较与百分比基数" aria-label="Permalink to &quot;Lesson 36 · 倍数比较与百分比基数 {#lesson-36-·-倍数比较与百分比基数}&quot;">​</a></h2><ul><li>account for — 占总量的某部分</li><li>increase by — 增加了某幅度</li></ul><p><strong>句型示范：</strong> In the fictional budget, maintenance costs rose from 100 units to 120 units, an increase of 20%.</p><p>from…to… 给起点终点；an increase of 20% 为同位补充，基数是原来的100。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-036">进入本课</a></p><h2 id="lesson-37-·-比较级重复与渐变表达" tabindex="-1">Lesson 37 · 比较级重复与渐变表达 <a class="header-anchor" href="#lesson-37-·-比较级重复与渐变表达" aria-label="Permalink to &quot;Lesson 37 · 比较级重复与渐变表达 {#lesson-37-·-比较级重复与渐变表达}&quot;">​</a></h2><ul><li>over the course of — 在某段时间过程中</li><li>at different rates — 以不同速度</li></ul><p><strong>句型示范：</strong> The records became more and more detailed over the course of the study.</p><p>more and more detailed 表渐变程度；over the course of… 限定变化发生的时间。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-037">进入本课</a></p><h2 id="lesson-38-·-if、when-后的省略结构" tabindex="-1">Lesson 38 · if、when 后的省略结构 <a class="header-anchor" href="#lesson-38-·-if、when-后的省略结构" aria-label="Permalink to &quot;Lesson 38 · if、when 后的省略结构 {#lesson-38-·-if、when-后的省略结构}&quot;">​</a></h2><ul><li>when in doubt — 有疑问时</li><li>check with — 向某人或机构核实</li></ul><p><strong>句型示范：</strong> When travelling, check current local guidance rather than rely on an old account.</p><p>When travelling 相当于 when you are travelling；主句祈使句隐含主语 you，与分词执行者相同。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-038">进入本课</a></p><h2 id="lesson-39-·-wish-后的时态与非现实意义" tabindex="-1">Lesson 39 · wish 后的时态与非现实意义 <a class="header-anchor" href="#lesson-39-·-wish-后的时态与非现实意义" aria-label="Permalink to &quot;Lesson 39 · wish 后的时态与非现实意义 {#lesson-39-·-wish-后的时态与非现实意义}&quot;">​</a></h2><ul><li>get across — 把意思传达清楚</li><li>revise for — 为某目标修改</li></ul><p><strong>句型示范：</strong> I wish the opening were shorter, because the main point arrives too late.</p><p>wish 后 were shorter 表对当前文本的不满意；because 从句说明修改理由。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-039">进入本课</a></p><h2 id="lesson-40-·-where-的地点与条件意义" tabindex="-1">Lesson 40 · where 的地点与条件意义 <a class="header-anchor" href="#lesson-40-·-where-的地点与条件意义" aria-label="Permalink to &quot;Lesson 40 · where 的地点与条件意义 {#lesson-40-·-where-的地点与条件意义}&quot;">​</a></h2><ul><li>travel through — 穿过某介质传播</li><li>under these conditions — 在这些条件下</li></ul><p><strong>句型示范：</strong> Where the water meets the barrier, the pattern changes.</p><p>where 从句指地点；主句 the pattern changes 描述该区域的观察结果。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-040">进入本课</a></p><h2 id="lesson-41-·-with-宾语-补足语" tabindex="-1">Lesson 41 · with + 宾语 + 补足语 <a class="header-anchor" href="#lesson-41-·-with-宾语-补足语" aria-label="Permalink to &quot;Lesson 41 · with + 宾语 + 补足语 {#lesson-41-·-with-宾语-补足语}&quot;">​</a></h2><ul><li>respond to — 对信号作出反应</li><li>take account of — 将某因素考虑在内</li></ul><p><strong>句型示范：</strong> With the observer standing at a distance, the handler recorded the animal’s response.</p><p>observer 与 standing 是主动关系；with 短语交代背景，主句主语是 handler。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-041">进入本课</a></p><h2 id="lesson-42-·-被动语态中的时态与体" tabindex="-1">Lesson 42 · 被动语态中的时态与体 <a class="header-anchor" href="#lesson-42-·-被动语态中的时态与体" aria-label="Permalink to &quot;Lesson 42 · 被动语态中的时态与体 {#lesson-42-·-被动语态中的时态与体}&quot;">​</a></h2><ul><li>pick up — 检测到微弱信号</li><li>be under review — 正在审查之中</li></ul><p><strong>句型示范：</strong> The signal has been recorded, but the data are still being analysed.</p><p>has been recorded 表已完成的记录；are being analysed 表正在进行的被动过程；data 在此按复数处理。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-042">进入本课</a></p><h2 id="lesson-43-·-there-be-与存在命题" tabindex="-1">Lesson 43 · there be 与存在命题 <a class="header-anchor" href="#lesson-43-·-there-be-与存在命题" aria-label="Permalink to &quot;Lesson 43 · there be 与存在命题 {#lesson-43-·-there-be-与存在命题}&quot;">​</a></h2><ul><li>search for — 寻找某对象</li><li>as yet — 到目前为止</li></ul><p><strong>句型示范：</strong> There may be a simpler explanation for the unusual signal.</p><p>there may be 为情态存在结构；a simpler explanation 是引入的新信息；for…限定解释对象。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-043">进入本课</a></p><h2 id="lesson-44-·-限制性与非限制性从句的范围差异" tabindex="-1">Lesson 44 · 限制性与非限制性从句的范围差异 <a class="header-anchor" href="#lesson-44-·-限制性与非限制性从句的范围差异" aria-label="Permalink to &quot;Lesson 44 · 限制性与非限制性从句的范围差异 {#lesson-44-·-限制性与非限制性从句的范围差异}&quot;">​</a></h2><ul><li>within a community — 在某个社群内部</li><li>from one context to another — 从一种情境到另一种情境</li></ul><p><strong>句型示范：</strong> The visitors who had attended the workshop recognised the greeting.</p><p>who…workshop 是限制性从句，只选出访客中的一部分；没有宣称全部访客参加过。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-044">进入本课</a></p><h2 id="lesson-45-·-no-more-than-与-not-more-than" tabindex="-1">Lesson 45 · no more than 与 not more than <a class="header-anchor" href="#lesson-45-·-no-more-than-与-not-more-than" aria-label="Permalink to &quot;Lesson 45 · no more than 与 not more than {#lesson-45-·-no-more-than-与-not-more-than}&quot;">​</a></h2><ul><li>put into practice — 将知识付诸实践</li><li>put into perspective — 放入适当背景理解</li></ul><p><strong>句型示范：</strong> The summary contained no more than three pages, yet it raised questions the committee had overlooked.</p><p>no more than 强调篇幅很短；yet 连接篇幅与作用的反差；had overlooked 表忽略先于摘要提出问题。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-045">进入本课</a></p><h2 id="lesson-46-·-would-rather-与-prefer-的补语" tabindex="-1">Lesson 46 · would rather 与 prefer 的补语 <a class="header-anchor" href="#lesson-46-·-would-rather-与-prefer-的补语" aria-label="Permalink to &quot;Lesson 46 · would rather 与 prefer 的补语 {#lesson-46-·-would-rather-与-prefer-的补语}&quot;">​</a></h2><ul><li>take up — 开始从事一种爱好</li><li>for its own sake — 为事情本身的价值</li></ul><p><strong>句型示范：</strong> I would rather repair an old radio than buy another one.</p><p>would rather 后 repair 与 than 后 buy 都是动词原形；another one 指另一台 radio。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-046">进入本课</a></p><h2 id="lesson-47-·-篇章指代与-this-概括名词" tabindex="-1">Lesson 47 · 篇章指代与 this + 概括名词 <a class="header-anchor" href="#lesson-47-·-篇章指代与-this-概括名词" aria-label="Permalink to &quot;Lesson 47 · 篇章指代与 this + 概括名词 {#lesson-47-·-篇章指代与-this-概括名词}&quot;">​</a></h2><ul><li>get away from — 暂时离开某环境</li><li>live up to — 达到某种期待</li></ul><p><strong>句型示范：</strong> We expected the trip to remove every worry. That expectation proved unrealistic.</p><p>That expectation 概括前句内容，明确指向“旅行消除所有烦恼”的想法，而非 trip 本身。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-047">进入本课</a></p><h2 id="lesson-48-·-决策段落中的-however、therefore-与条件" tabindex="-1">Lesson 48 · 决策段落中的 however、therefore 与条件 <a class="header-anchor" href="#lesson-48-·-决策段落中的-however、therefore-与条件" aria-label="Permalink to &quot;Lesson 48 · 决策段落中的 however、therefore 与条件 {#lesson-48-·-决策段落中的-however、therefore-与条件}&quot;">​</a></h2><ul><li>depend on — 取决于具体条件</li><li>take into account — 将某因素纳入考虑</li></ul><p><strong>句型示范：</strong> The two plans serve different objectives; therefore, comparing returns alone would be misleading.</p><p>分号连接独立分句；therefore 表由目标不同推导出的比较限制；comparing… 为动名词主语。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-048">进入本课</a></p>',123)])])}const f=o(l,[["render",t]]);export{d as __pageData,f as default};
